"""Record the nine local native-geometry views actually inspected in this session."""
import hashlib,json
from pathlib import Path
b=Path('robot/.state/c3-completion/trials');o=b/'R156G-visual-review.json';assert not o.exists()
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();i=json.loads((b/'R156G-inspection.json').read_text());images=[{'path':'images/'+p.name,'sha256':sha(p),'svg_path':'images/'+p.with_suffix('.svg').name,'svg_sha256':sha(p.with_suffix('.svg'))} for p in sorted((b/'R156G-views').glob('*.png'))];assert len(images)==9
reviews={
'U1701':'Four front WHEEL_VM sense segments project over the existing back INA300 body. The new branch serves only the 100k divider; load copper, INA300 input pair, limit resistor, local bypass and every ground via are unchanged. The full new front trace is over the unchanged In1 GND plane and the back circuit retains its In4 reference; no new drill voids are introduced. Input coupling, transient response, actual ground impedance and thermal behavior remain NOT_TESTED.',
'C505':'Two short middle-node segments have small nominal projections over the unchanged back decoupling capacitor. Front and back escapes stay outside their own body; In1/In4 reference fills are unchanged. C505 supply through the original In3 plane and all source width gates is preserved after removing redundant front 3V3 links. High-frequency bypass performance, capacitive coupling and thermal behavior remain NOT_TESTED.'}
assert set(reviews)=={p['reference'] for t in i['new_tracks'] for p in t['nominal_body_projections']}
r={'scope':__doc__,'board_sha256':i['candidate_sha256'],'source_sha256':i['source_sha256'],'local_status':'PASS','images_actually_viewed':images,'findings':['R1702 rotates 180 to 0 degrees in place; R1703 translates +0.55,-0.42 mm to (49.05,9.98). Values and pin nets are unchanged.','The two-resistor middle-node route becomes 1.728528 mm instead of 2.107107 mm. R1703 output is a single straight 2.47 mm vertical segment joining the unchanged long INA+ trunk.','The new 0.20 mm WHEEL_VM sense branch is 8.147372 mm, follows deliberate diagonal/vertical bends around fixed ground and supply holes, and joins the original R1101.2 land without a new via. It does not carry actuator load current.','Ten source segments are removed and eleven are added. Six removed 0.35 mm front 3V3 inter-via segments are geometrically redundant with the unchanged In3 3V3 fill; all fifty old width tests and additional local via/capacitor comparisons are preserved.','The original In2/In3 3V3 fills and In1/In4 GND fills have zero geometric symmetric difference. Every supply/ground via stays fixed, and the back escape geometry remains unchanged.','R1702 and R1703 native courtyards now have 0.03 mm gap; R1703.2 to the fixed nearby GND via has 0.296262 mm copper gap. These library/native distances are not assembly tolerance qualification.','All eleven new tracks were checked against nominal Fab bodies outside same-net lands; there are zero new mounted-face hits. Opposite-face projections are limited to C505 and U1701 and reviewed separately.','The symmetric R1702 native body guard is geometrically invariant under the exact 180 degree rotation. R1703 guard moves exactly with its part; no guard is removed or weakened.'],'same_face_nominal_body_hit_count':0,'opposite_body_reviews':[{'reference':ref,'review':text,'thermal_and_coupling':'NOT_TESTED; geometric reference and original circuits preserved'} for ref,text in reviews.items()],'limits':['These are native-geometry diagnostic plots, not GUI screenshots or physical measurements.','Nominal Fab/courtyard data are not measured complete component envelopes.','No full-board layout/return/current/thermal/EMC or assembled qualification follows from this local reception.','Six historical reference-transition flags remain.'],'whole_board':'NOT_TESTED','physical':'NOT_TESTED','manufacturing_release':False}
o.write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({'images_actually_viewed':len(images),'new_same_face_hits':0,'opposite_reviewed':list(reviews)}))
